#include <stdio.h>

int main(void) {
    int n, tamanho;
    char lado;
    int esquerda[61] = {0};
    int direita[61] = {0};
    int pares = 0;

    scanf("%d", &n);

    for (int i = 0; i < n; i++) {
        scanf("%d %c", &tamanho, &lado);
        if (lado == 'E')
            esquerda[tamanho]++;
        else
            direita[tamanho]++;
    }

    for (int tamanho = 30; tamanho <= 60; tamanho++) {
        pares += esquerda[tamanho] < direita[tamanho]
                     ? esquerda[tamanho]
                     : direita[tamanho];
    }

    printf("%d\n", pares);
    return 0;
}
